function numIslands(grid: string[][]): number {
  const m = grid.length
  const n = grid[0].length
  let count = 0
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] !== '1') continue
      count++
      const stack = [[r, c]]
      grid[r][c] = '0'
      while (stack.length) {
        const [y, x] = stack.pop()!
        for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const ny = y + dy
          const nx = x + dx
          if (ny >= 0 && nx >= 0 && ny < m && nx < n && grid[ny][nx] === '1') {
            grid[ny][nx] = '0'
            stack.push([ny, nx])
          }
        }
      }
    }
  }
  return count
}
